<?= view('partials/admin_sidebar',['active'=>'media']) ?>
<main class="admin-main"><header class="admin-topbar"><div><span class="eyebrow accent">DYNAMIC GALLERY & VIDEO</span><h1>Media manager</h1><p>Control homepage hero, highlights, featured video, line-up and gallery order from one place.</p></div></header>
  <section class="admin-panel"><form class="admin-form media-form" method="post" action="<?= base_url('admin/media') ?>" enctype="multipart/form-data" data-testid="media-create-form"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><label>Type<select name="media_type" data-testid="media-type"><option value="image">Image</option><option value="video">Video URL</option></select></label><label>Section<select name="section" data-testid="media-section"><?php foreach(['hero','highlight','featured','lineup','gallery'] as $section): ?><option value="<?= $section ?>"><?= ucfirst($section) ?></option><?php endforeach ?></select></label><label>Title<input name="title" required minlength="2" data-testid="media-title"></label><label>Caption<input name="caption" data-testid="media-caption"></label><label>Event<select name="event_id" data-testid="media-event"><option value="">No event</option><?php foreach($events as $event): ?><option value="<?= $event['id'] ?>"><?= esc($event['name']) ?></option><?php endforeach ?></select></label><label>Display order<input type="number" name="display_order" min="0" value="0" data-testid="media-order"></label><label class="admin-span-2">Image upload / video thumbnail<input type="file" name="image" accept="image/jpeg,image/png,image/webp" data-testid="media-image"></label><label class="admin-span-2">Image or YouTube/Vimeo/MP4 URL<input type="url" name="source_url" placeholder="https://…" data-testid="media-url"></label><label class="admin-span-2">Optional video thumbnail URL<input type="url" name="thumbnail_url" placeholder="https://…" data-testid="media-thumbnail"></label><label class="check-label"><input type="checkbox" name="is_active" value="1" checked data-testid="media-active"> Active</label><button class="button button-yellow admin-span-2" type="submit" data-testid="media-submit">Add media item</button></form></section>
  <section class="admin-panel"><div class="admin-panel-heading"><div><span class="eyebrow">PUBLISHED ASSETS</span><h2><?= count($media) ?> media items</h2></div></div><div class="media-admin-list"><?php foreach($media as $item): ?><form class="media-admin-item" method="post" action="<?= base_url('admin/media/'.$item['id']) ?>" data-testid="media-row-<?= $item['id'] ?>"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><input type="hidden" name="media_type" value="<?= esc($item['media_type']) ?>"><div class="media-admin-thumb"><?php if($item['storage_path']): ?><img src="<?= base_url('media/file/'.$item['id']) ?>" alt=""><?php elseif($item['thumbnail_url']||$item['source_url']): ?><img src="<?= esc($item['thumbnail_url']?:$item['source_url']) ?>" alt=""><?php endif ?></div><div class="media-admin-edit"><input name="title" value="<?= esc($item['title']) ?>" required><input name="caption" value="<?= esc($item['caption']) ?>"><div><select name="section"><?php foreach(['hero','highlight','featured','lineup','gallery'] as $section): ?><option value="<?= $section ?>" <?= $item['section']===$section?'selected':'' ?>><?= ucfirst($section) ?></option><?php endforeach ?></select><select name="event_id"><option value="">No event</option><?php foreach($events as $event): ?><option value="<?= $event['id'] ?>" <?= (int)$item['event_id']===(int)$event['id']?'selected':'' ?>><?= esc($event['name']) ?></option><?php endforeach ?></select><input type="number" name="display_order" min="0" value="<?= $item['display_order'] ?>"></div><input name="source_url" value="<?= esc($item['source_url']) ?>" placeholder="Source URL"><input name="thumbnail_url" value="<?= esc($item['thumbnail_url']) ?>" placeholder="Thumbnail URL"></div><div class="media-admin-actions"><label><input type="checkbox" name="is_active" value="1" <?= $item['is_active']?'checked':'' ?>> Active</label><button type="submit" data-testid="media-save-<?= $item['id'] ?>">Save</button><button type="submit" formaction="<?= base_url('admin/media/'.$item['id'].'/delete') ?>" class="danger" onclick="return confirm('Delete this media item?')" data-testid="media-delete-<?= $item['id'] ?>">Delete</button></div></form><?php endforeach ?></div></section>
</main>